class Solution:
    def longestSpecialPath(self, edges, nums):
        n = len(nums)
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w)); g[v].append((u, w))
        dist = [0] * n
        path, pos = [], {}
        ans = [0, 1]
        def dfs(u, p):
            d = len(path); path.append(u)
            occ = pos.setdefault(nums[u], [])
            start = occ[-2] + 1 if len(occ) >= 2 else 0
            occ.append(d)
            length = dist[u] - (dist[path[start]] if start else 0)
            cnt = d - start + 1
            if length > ans[0] or (length == ans[0] and cnt < ans[1]):
                ans[0], ans[1] = length, cnt
            for v, w in g[u]:
                if v != p:
                    dist[v] = dist[u] + w
                    dfs(v, u)
            occ.pop(); path.pop()
        dfs(0, -1)
        return ans

