class Solution {
public:
    vector<int> longestSpecialPath(vector<vector<int>>& edges, vector<int>& nums) {
        int n = nums.size();
        vector<vector<pair<int,int>>> g(n);
        for (auto& e : edges) { g[e[0]].push_back({e[1], e[2]}); g[e[1]].push_back({e[0], e[2]}); }
        vector<long long> dist(n);
        vector<int> path;
        unordered_map<int, vector<int>> pos;
        long long bestLen = 0; int bestCnt = 1;
        function<void(int,int)> dfs = [&](int u, int p) {
            int d = path.size(); path.push_back(u);
            auto& occ = pos[nums[u]];
            int start = occ.size() >= 2 ? occ[occ.size() - 2] + 1 : 0;
            occ.push_back(d);
            long long len = dist[u] - (start ? dist[path[start]] : 0);
            int cnt = d - start + 1;
            if (len > bestLen || (len == bestLen && cnt < bestCnt)) { bestLen = len; bestCnt = cnt; }
            for (auto [v, w] : g[u]) if (v != p) { dist[v] = dist[u] + w; dfs(v, u); }
            occ.pop_back(); path.pop_back();
        };
        dfs(0, -1);
        return {(int)bestLen, bestCnt};
    }
};

