class Solution {
    private List<int[]>[] g;
    private int[] nums;
    private long[] dist;
    private List<Integer> path;
    private Map<Integer, List<Integer>> pos;
    private long bestLen = 0;
    private int bestCnt = 1;

    public int[] longestSpecialPath(int[][] edges, int[] nums) {
        int n = nums.length;
        this.nums = nums;
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) {
            g[e[0]].add(new int[]{e[1], e[2]});
            g[e[1]].add(new int[]{e[0], e[2]});
        }
        dist = new long[n];
        path = new ArrayList<>();
        pos = new HashMap<>();
        dfs(0, -1);
        return new int[]{(int) bestLen, bestCnt};
    }

    private void dfs(int u, int p) {
        int d = path.size();
        path.add(u);
        List<Integer> occ = pos.computeIfAbsent(nums[u], k -> new ArrayList<>());
        int start = occ.size() >= 2 ? occ.get(occ.size() - 2) + 1 : 0;
        occ.add(d);
        long len = dist[u] - (start > 0 ? dist[path.get(start)] : 0);
        int cnt = d - start + 1;
        if (len > bestLen || (len == bestLen && cnt < bestCnt)) { bestLen = len; bestCnt = cnt; }
        for (int[] e : g[u]) if (e[0] != p) { dist[e[0]] = dist[u] + e[1]; dfs(e[0], u); }
        occ.remove(occ.size() - 1);
        path.remove(path.size() - 1);
    }
}

