var longestSpecialPath = function(edges, nums) {
    const n = nums.length, g = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) { g[u].push([v, w]); g[v].push([u, w]); }
    const dist = new Array(n).fill(0), path = [], pos = new Map();
    let bestLen = 0, bestCnt = 1;
    function dfs(u, p) {
        const d = path.length; path.push(u);
        let occ = pos.get(nums[u]); if (!occ) { occ = []; pos.set(nums[u], occ); }
        const start = occ.length >= 2 ? occ[occ.length - 2] + 1 : 0;
        occ.push(d);
        const len = dist[u] - (start > 0 ? dist[path[start]] : 0);
        const cnt = d - start + 1;
        if (len > bestLen || (len === bestLen && cnt < bestCnt)) { bestLen = len; bestCnt = cnt; }
        for (const [v, w] of g[u]) if (v !== p) { dist[v] = dist[u] + w; dfs(v, u); }
        occ.pop(); path.pop();
    }
    dfs(0, -1);
    return [bestLen, bestCnt];
};
